 function transaction(fn){const snapshot=JSON.stringify({stars:profile.stars,u:profile.dinoUniverse,pet:p});const result=fn();if(!result?.ok){api.toast(result?.msg||'Radnja nije dostupna.');return false}if(!save()){const old=JSON.parse(snapshot);profile.stars=old.stars;profile.dinoUniverse=old.u;profile.dino[sp]=old.pet;p=profile.dino[sp];save();update('Promjena nije spremljena. Provjeri lokalno spremanje.');return false}api.sound('tap');update(result.msg);api.toast(result.msg);return true;}
 function universeClick(b){
  if(b.dataset.duFilter){shopRoom=b.dataset.duFilter;extra();return}
  if(b.dataset.duTab){tab=b.dataset.duTab;shopRoom='all';extra();return}
  if(b.dataset.duBuy){const i=U.items[b.dataset.duBuy];if(i&&confirm(`Kupiti ${i.name} za ${i.price} zvjezdica?`))transaction(()=>U.buy(profile,i.id));return}
  if(b.dataset.duEquip){const i=U.items[b.dataset.duEquip];if(i?.slot==='plant'&&p.universe.plant&&p.universe.plant.id!==i.id&&!confirm('Zamijeniti postojeći cvijet? Novi počinje od sjemena.'))return;if(transaction(()=>{const r=U.equip(profile,p,b.dataset.duEquip);if(r.ok){p.room=r.room;tool='';reaction=''}return r})){$('#dlStage',root).scrollIntoView({block:'center',behavior:'instant'})}return}
  if(b.hasAttribute('data-du-water')){transaction(()=>U.water(profile,p));return}
  if(b.dataset.duRoute){const r=U.routeMap[b.dataset.duRoute];if(r&&confirm(`${p.name} ide na ekspediciju ${r.name} (${r.minutes} min). Do povratka ne možeš izvršavati aktivnosti brige. Krenuti?`)){if(visibleTime>0)decay(p,visibleTime);visibleTime=0;const ok=transaction(()=>U.depart(profile,p,r.id));wasAway=U.activeTrip(p);if(ok)tool='';}return}
  if(b.hasAttribute('data-du-claim')){transaction(()=>U.claim(profile,p));return}
 }

