 api.on(root,'click',e=>{const a=e.target.closest('[data-dl-action]'),tabBtn=e.target.closest('[data-dl-tab]'),acc=e.target.closest('[data-dl-accessory]'),pet=e.target.closest('[data-dl-pet]');if(api.paused)return;if(e.target.closest('[data-cw-farm]')){api.launch('fruit',{mode:'farm'});return;}const du=e.target.closest('[data-du-buy],[data-du-equip],[data-du-water],[data-du-route],[data-du-claim],[data-du-filter],[data-du-tab]');if(du&&!du.disabled){universeClick(du);return}const room=e.target.closest('[data-dh-room]'),toolBtn=e.target.closest('[data-dh-tool]');if(room&&!room.disabled)changeRoom(room.dataset.dhRoom);else if(toolBtn&&!toolBtn.disabled){if(performance.now()>ignoreClickUntil)chooseTool(toolBtn.dataset.dhTool);}else if(a&&!a.disabled)interact(a.dataset.dlAction);else if(tabBtn){tab=tab===tabBtn.dataset.dlTab?'care':tabBtn.dataset.dlTab;shopRoom='all';extra();if(tab!=='care')$('#dlExtra',root).scrollIntoView({block:'start',behavior:'instant'});}else if(e.target.closest('[data-dl-close]')){tab='care';extra();}else if(acc&&!acc.disabled){const option=accessories.find(a=>a.id===acc.dataset.dlAccessory);if(option&&!asleep(p)&&!U.activeTrip(p)&&p.care>=Math.max(3,option.at)){p.accessory=option.id;save();draw();extra();api.sound('tap')}}else if(pet)choose(pet.dataset.dlPet)});
 $('#dlSpecies',root).onchange=e=>choose(e.target.value);$('#dlHabSelect',root).onchange=e=>{if(api.paused||U.activeTrip(p)||asleep(p))return;p.habitat=valid(habitats,e.target.value,'forest');profile.options.dino.habitat=p.habitat;save();draw();api.sound('tap')};
 const rename=()=>{if(api.paused)return;p.name=cleanName($('#dlNameInput',root).value,dinos[sp].name);$('#dlNameInput',root).value=p.name;save();draw();extra();$('#dlMessage',root).textContent=`Tvoj se prijatelj zove ${p.name}.`};$('#dlNameForm',root).onsubmit=e=>{e.preventDefault();rename()};$('#dlNameInput',root).onchange=rename;
 $('#dlTouch',root).onclick=()=>interact('pet');$('#dlLeave',root).onclick=()=>api.leave?.();const hit=$('#dhTarget',root);hit.onclick=()=>{if(performance.now()<ignoreTargetClickUntil||api.paused||asleep(p)||U.activeTrip(p))return;if(tool)useTool();else if(p.room==='garden')interact('pet')};
 $('#dhReset',root).onclick=()=>{if(api.paused)return;if(!confirm(`Želiš li vratiti dinosaura „${p.name}” u jaje? Izgubit će ime, rast, potrebe i vlastite ukrase, uređenje i nepreuzetu ekspediciju. Kupljeni predmeti, album otkrića, ostali dinosauri, zajedničke medalje, XP i zvjezdice ostaju. Ovo se ne može poništiti.`))return;clearTimeout(fxTimer);visibleTime=0;lastAction=-100;tool='';reaction='';p=resetPet(profile,sp);wasAway=false;$('#dlNameInput',root).value=p.name;$('#dlHabSelect',root).value=p.habitat;tab='care';save();update('Novo čarobno jaje spremno je za novi početak.');};
 const ghost=$('#dhDrag',root),stage=$('#dlStage',root);root.appendChild(ghost);
