 function endDrag(e,cancel=false){if(!drag||drag.pid!==e.pointerId)return;const d=drag;drag=null;ghost.hidden=true;stage.classList.remove('dh-dragging');if(d.moved){ignoreClickUntil=performance.now()+350;const r=stage.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(!cancel&&x>.20&&x<.83&&y>.20&&y<.90){tool=d.id;useTool(d.id)}else if(!cancel){$('#dlMessage',root).textContent='Povuci predmet do dinosaura u sredini scene.';}}}
