 api.on(hit,'pointerdown',e=>{const id=tool|| (p.room==='garden'?'pet':'');if(!['soap','rinse','pet'].includes(id)||rub||drag||api.paused||asleep(p)||U.activeTrip(p)||e.button>0)return;rub={pid:e.pointerId,id,x:e.clientX,y:e.clientY,d:0,moved:false,sp,done:false};try{hit.setPointerCapture(e.pointerId)}catch(_){} });
